#!/usr/bin/env python3
"""Rebuilds cpp/fx/, cpp/registry.inc and src/list.rs from a checkout of Airwindows Consolidated
(https://github.com/baconpaul/airwin2rack, MIT): `gen.py <airwin2rack checkout>`. It keeps the effects Airwindows lists
as "Recommended" or "Basic" (139 of 533) and needs a C++17 compiler (c++) once, to read each effect's parameter names
and defaults."""
import html, json, os, re, shutil, subprocess, sys, tempfile

SRC = sys.argv[1]
HERE = os.path.dirname(os.path.abspath(__file__))
AG = os.path.join(SRC, "src", "autogen_airwin")

rows = []
for line in open(os.path.join(SRC, "src", "ModuleAdd.h")):
    if not line.startswith("int ") or "registerAirwindow" not in line:
        continue
    m = re.search(
        r'registerAirwindow\(\{"(\w+)", "([^"]*)", (-?\d+), (true|false), "((?:[^"\\]|\\.)*)", '
        r'airwinconsolidated::\w+::kNumParameters, "[^"]*", (\[\]\(\) \{ return std::make_unique<[^;]*; \}), -1, \{(.*?)\}\}\);',
        line,
    )
    assert m, line[:100]
    name, cat, _, _, what, make, cols = m.groups()
    if not re.search(r'"(Recommended|Basic)"', cols):
        continue
    rows.append(dict(name=name, cat=cat, what=what.replace('\\"', '"'), make=make))
rows.sort(key=lambda r: (r["cat"], r["name"].lower()))
cats = sorted({r["cat"] for r in rows})

fx = os.path.join(HERE, "cpp", "fx")
shutil.rmtree(fx, ignore_errors=True)
os.makedirs(fx)
for r in rows:
    for ext in (".h", ".cpp", "Proc.cpp"):
        shutil.copy(os.path.join(AG, r["name"] + ext), fx)
for f in ("airwin_consolidated_base.h", "airwin_consolidated_base.cpp"):
    shutil.copy(os.path.join(SRC, "src", f), os.path.join(HERE, "cpp", f))
# The effects include the base as "../airwin_consolidated_base.h".

with open(os.path.join(HERE, "cpp", "registry.inc"), "w") as f:
    f.write("// Generated by gen.py: the effects, in the order of src/list.rs.\n")
    for r in rows:
        f.write(f'#include "fx/{r["name"]}.h"\n')
    f.write("static const Entry ENTRIES[] = {\n")
    for r in rows:
        f.write(f'    {{"{r["name"]}", airwinconsolidated::{r["name"]}::kNumParameters, {r["make"]}}},\n')
    f.write("};\n")

# Read the parameter names and defaults off the effects themselves.
dump = r'''
#include "aw_entry.h"
#include "registry.inc"
#include <cstdio>
int main() {
    for (const Entry &e : ENTRIES) {
        auto fx = e.make();
        fx->setSampleRate(44100.f);
        printf("%s", e.name);
        for (int p = 0; p < e.params; ++p) {
            char name[64] = {0};
            fx->getParameterName(p, name);
            printf("\t%s\t%d", name, (int)(fx->getParameter(p) * 1000.f + 0.5f));
        }
        printf("\n");
    }
}
'''
tmp = tempfile.mkdtemp()
open(os.path.join(tmp, "dump.cc"), "w").write(dump)
cc = os.environ.get("CXX", "c++")
objs = []
srcs = [os.path.join(HERE, "cpp", "airwin_consolidated_base.cpp")]
srcs += [os.path.join(fx, r["name"] + s) for r in rows for s in (".cpp", "Proc.cpp")]
cpp = os.path.join(HERE, "cpp")
for s in srcs + [os.path.join(tmp, "dump.cc")]:
    o = os.path.join(tmp, re.sub(r"\W", "_", s) + ".o")
    subprocess.check_call([cc, "-std=c++17", "-O0", "-w", "-I", cpp, "-c", s, "-o", o])
    objs.append(o)
subprocess.check_call([cc, *objs, "-o", os.path.join(tmp, "dump")])
out = subprocess.check_output([os.path.join(tmp, "dump")], text=True).splitlines()
shutil.rmtree(tmp)

def rs(s):
    return json.dumps(s, ensure_ascii=False)

with open(os.path.join(HERE, "src", "list.rs"), "w") as f:
    f.write("// Generated by gen.py from Airwindows Consolidated (MIT): the effects, their categories, parameter names and defaults.\n")
    f.write("pub struct Fx {\n    pub name: &'static str,\n    pub category: usize,\n    pub what: &'static str,\n")
    f.write("    /// Each parameter's name and default, in thousandths.\n    pub params: &'static [(&'static str, u16)],\n}\n\n")
    f.write(f"pub static CATEGORIES: [&str; {len(cats)}] = [{', '.join(rs(c) for c in cats)}];\n\n")
    f.write(f"pub static FX: [Fx; {len(rows)}] = [\n")
    for r, line in zip(rows, out):
        parts = line.split("\t")
        assert parts[0] == r["name"]
        params = ", ".join(f"({rs(parts[i])}, {parts[i + 1]})" for i in range(1, len(parts), 2))
        f.write(f"    Fx {{ name: {rs(r['name'])}, category: {cats.index(r['cat'])}, what: {rs(html.unescape(r['what']))}, params: &[{params}] }},\n")
    f.write("];\n")
print(len(rows), "effects,", len(cats), "categories")
